mapper.sql:
select cgsl.road_name, cgslam.adsi_nm , cgslam.adstdg_nm , round(avg(collector.avg_speed), 2) as avgSpeed from adsi_vds_sctn_stlink_mppg avssm inner join adsi_vds_sctn_info avsi on avssm.vds_sctn_id = avsi.vds_sctn_id inner join adsi_vds_colct_info_cur collector on avsi.vds_id = collector.vds_id inner join c_gm_std_link_tmp cgsl on avssm.std_link_id = cgsl.link_id inner join c_gm_std_link_adstdg_mppg cgslam on cgsl.link_id = cgslam.link_id
AND TO_CHAR(collector.clct_dt, 'HH24') = #{schTime}
AND SUBSTRING(CGSLAM.ADSTDG_CD,0,5) = SUBSTRING(#{mngInstCd},0,5)
AND CGSLAM.adstdg_nm = #{dongNm}
AND CGSL.ROAD_NAME LIKE '%' || #{schRoadName} || '%'
group by 1,2,3 order by 2 desc

select cgsl.road_name, cgslam.adsi_nm , cgslam.adstdg_nm , sum(collector.trfvlm) as trfVol from adsi_vds_sctn_stlink_mppg avssm inner join adsi_vds_sctn_info avsi on avssm.vds_sctn_id = avsi.vds_sctn_id inner join adsi_vds_colct_info_cur collector on avsi.vds_id = collector.vds_id inner join c_gm_std_link_tmp cgsl on avssm.std_link_id = cgsl.link_id inner join c_gm_std_link_adstdg_mppg cgslam on cgsl.link_id = cgslam.link_id
AND TO_CHAR(collector.clct_dt, 'HH24') = #{schTime}
AND SUBSTRING(CGSLAM.ADSTDG_CD,0,5) = SUBSTRING(#{mngInstCd},0,5)
AND CGSLAM.adstdg_nm = #{dongNm}
AND CGSL.ROAD_NAME LIKE '%' || #{schRoadName} || '%'
group by 1,2,3 order by 2 desc

mapper.select:
select * from ( select row_number() OVER(ORDER BY avgSpeed desc) AS rnk, adsi_nm, adstdg_nm, avgSpeed, road_name from (
) ranking ) paging
LIMIT 5 OFFSET (#{page} - 1) * 5

select * from ( select row_number() OVER(ORDER BY trfVol desc) AS rnk, adsi_nm, adstdg_nm, trfVol, road_name from (
) ranking ) paging
LIMIT 5 OFFSET (#{page} - 1) * 5

